SourceCode.Declaration:
/// <summary>
/// Handles processing of selected purchase order lines to determine whether they belong
/// to a confirmed purchase order version. No deletion is performed; only warnings are issued.
/// </summary>
internal final class METISPPurchLineStripDelete
{
    List poLinesToDelete;

}

Method.Source:
/// <summary>
/// Factory method to create an instance of this class.
/// </summary>
/// <param name="_poLinesToDelete">List of PurchLine records to process.</param>
/// <returns>Instance of METISPPurchLineStripDelete.</returns>
public static METISPPurchLineStripDelete construct(List _poLinesToDelete)
{
    return new METISPPurchLineStripDelete(_poLinesToDelete);
}

/// <summary>
/// Initializes the instance with the provided list of purchase lines.
/// </summary>
/// <param name="_poLinesToDelete">List of PurchLine records.</param>
protected void new(List _poLinesToDelete)
{
    poLinesToDelete = _poLinesToDelete;
}

/// <summary>
/// Entry point when executed from a menu item.
/// Collects selected PO lines, processes them, and marks confirmed lines on the form.
/// </summary>
/// <param name="_args">Arguments containing the PurchLine record context.</param>
public static void main(Args _args)
{
    if (!_args)
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    PurchLine purchLine = _args.record();
    FormDataSource fds = FormDataUtil::getFormDataSource(purchLine);

    if (purchLine && fds)
    {
        List list = new List(Types::Record);
        PurchLine purchLineDelete;

        for (purchLineDelete = fds.getFirst(1) ? fds.getFirst(1) : fds.cursor();
        purchLineDelete;
        purchLineDelete = fds.getNext())
        {
            list.addEnd(purchLineDelete);
        }

        METISPPurchLineStripDelete del = METISPPurchLineStripDelete::construct(list);
        del.run();

        for (purchLineDelete = fds.getFirst(1) ? fds.getFirst(1) : fds.cursor();
        purchLineDelete;
        purchLineDelete = fds.getNext())
        {
            PurchLineAllVersions purchLineAllVersions = del.getPurchLineAllVersions(purchLineDelete);

            if (purchLineAllVersions.RecId)
            {
                fds.markRecord(purchLineDelete, 0);
            }
        }

        fds.getFirst(1);
    }
}

/// <summary>
/// Executes validation and processing of the purchase lines.
/// </summary>
protected void run()
{
    if (this.validate())
    {
        this.processPOLines();
    }
}

/// <summary>
/// Validates that at least one purchase line has been selected.
/// </summary>
/// <returns>True if valid; otherwise false.</returns>
protected boolean validate()
{
    if (poLinesToDelete.empty())
    {
        return checkFailed("@MET:NoPOLineSelectedDelete");
    }
    return true;
}

/// <summary>
/// Retrieves the PurchLineAllVersions record for the given PurchLine,
/// but only if it belongs to a confirmed purchase order version.
/// </summary>
/// <param name="_purchLine">The PurchLine to evaluate.</param>
/// <returns>Matching PurchLineAllVersions record, or an empty buffer if none found.</returns>
protected PurchLineAllVersions getPurchLineAllVersions(PurchLine _purchLine)
{
    PurchLineAllVersions purchLineAllVersions;
    PurchTableVersion    purchTableVersion;
    VendPurchOrderJour   vendPurchOrderJour;

    select firstonly RecId from purchLineAllVersions
        where purchLineAllVersions.InventTransId == _purchLine.InventTransId
    exists join purchTableVersion
         where purchTableVersion.RecId == purchLineAllVersions.PurchTableVersionRecId
    exists join vendPurchOrderJour
        where vendPurchOrderJour.PurchTableVersion == purchTableVersion.RecId;

    return purchLineAllVersions;
}

/// <summary>
/// Processes each selected purchase line and issues warnings for lines
/// that belong to confirmed purchase order versions. No deletion occurs.
/// </summary>
protected void processPOLines()
{
    ListEnumerator le = poLinesToDelete.getEnumerator();
    PurchLine purchLine;
    PurchLineAllVersions purchLineAllVersions;

    while (le.moveNext())
    {
        purchLine = le.current();

        try
        {
            ttsbegin;

            purchLineAllVersions = this.getPurchLineAllVersions(purchLine);

            if (purchLineAllVersions.RecId)
            {
                warning(strFmt("@MET:CannotDeletePOLineConfirmed", purchLine.LineNumber, purchLine.ItemId));
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            warning(strFmt("@MET:CannotDeletePOLine", purchLine.LineNumber, purchLine.ItemId));
        }
    }
}
